// Normal attacks are fixed by job; only the two distinct ultimates are selectable.
function combatTechnique(){return {normal:0,ultimate:p?.combatTechniques?.[currentJob()]?.ultimate===1?1:0};}
configuredUltimateCost=()=>100;
configuredCompactUltimate=()=>false;
const techniqueSaveBase=validateSave;validateSave=data=>{const out=techniqueSaveBase(data),src=data.p.combatTechniques;if(src!==undefined){if(!src||typeof src!=='object'||Array.isArray(src))throw Error('技の設定が不正です');out.p.combatTechniques={};for(const [key,value]of Object.entries(src)){if(!/^(?:[0-9]|1[0-5])$/.test(key)||!value||![0,1,2].includes(value.normal)||![0,1].includes(value.ultimate))throw Error('技の設定が不正です');out.p.combatTechniques[key]={normal:0,ultimate:value.ultimate};}}return out;};
function chooseCombatTechnique(kind,index){if(!paused||!started||dead||kind!=='ultimate'||![0,1].includes(index))return false;const old=p.combatTechniques;p.combatTechniques={...old,[currentJob()]:{normal:0,ultimate:index}};if(save()===false){if(old===undefined)delete p.combatTechniques;else p.combatTechniques=old;say('保存できなかったため変更を戻しました');return false;}panel('gems');iconSelectEntry('ultimate');return true;}
function combatUltimateOptions(job=currentJob()){const base=PROFESSIONS[job%8],alt=ALTERNATE_ULTIMATES[job%8];return [{name:base.ultimate,desc:base.desc},{name:alt.name,desc:alt.desc}];}
function combatLoadoutEntries(){const selected=combatTechnique(),options=combatUltimateOptions();return [{key:'normal-attack',label:'通常攻撃',icon:menuIcon('weapon'),nodes:[loadoutNode('<p>'+gearEscape(profession().name)+'</p>'+jobGuideContent('basic',currentJob())+'<p>この職業専用の通常攻撃 · SP '+staminaCost(0).toFixed(1)+'</p>')]},{key:'ultimate',label:'必殺技：'+options[selected.ultimate].name,icon:menuIcon('skills'),nodes:[...options.flatMap((t,i)=>[loadoutNode('<h3>'+gearEscape(t.name)+'</h3><p>'+gearEscape(t.desc)+'</p><p>必殺ゲージ100'+(advancedJob()?' · 上位職の威力補正あり':'')+'</p>'),loadoutAction((i===selected.ultimate?'✓ 装備中：':'装備する：')+t.name,()=>chooseCombatTechnique('ultimate',i))])]}];}
